#include <iostream>

// Least privilege: values are read-only (const int*), size is read-only (const size_t)
void printArray(const int* arr, const size_t size) {
    for (size_t i = 0; i < size; ++i) {
        std::cout << arr[i] << (i + 1 < size ? " " : "\n");
    }
}

int main() {
    // Built-in array limitation: cannot be assigned or compared directly with ==
    int numbers[] = {10, 20, 30, 40, 50};
    const size_t size = sizeof(numbers) / sizeof(numbers[0]);

    std::cout << "Array elements: ";
    printArray(numbers, size);

    return 0;
}

#include <iostream>

int main() {
    int a = 10;
    int b = 20;

    // 1. Nonconstant pointer to constant data
    const int* ptrToConst = &a;
    std::cout << "ptrToConst points to: " << *ptrToConst << "\n";
    ptrToConst = &b; // Allowed: pointer can be redirected
    std::cout << "ptrToConst redirected to: " << *ptrToConst << "\n";
    // *ptrToConst = 30; // Compilation error: data is read-only

    // 2. Constant pointer to nonconstant data
    int* const constPtr = &a;
    *constPtr = 15; // Allowed: data can be modified
    std::cout << "Value of a after mutation via constPtr: " << a << "\n";
    // constPtr = &b; // Compilation error: pointer cannot be reassigned

    // 3. Constant pointer to constant data
    const int* const fullyConst = &b;
    std::cout << "fullyConst points to: " << *fullyConst << "\n";
    // *fullyConst = 99; // Compilation error: data is const
    // fullyConst = &a;  // Compilation error: pointer is const

    return 0;
}
